<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{$vps->hostname?:('VPS #'.$vps->id)}} · Nodexa</title><style>:root{--bg:#06111d;--surface:#0b1927;--surface2:#0e2031;--line:#1b3449;--blue:#3b8cff;--text:#f1f6fb;--muted:#7f94a8;--green:#35d39a;--red:#ff6175;--orange:#ffb84d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,system-ui,-apple-system,"Segoe UI",sans-serif}a{text-decoration:none;color:inherit}.top{height:68px;background:#081522;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 max(22px,calc((100% - 1240px)/2))}.brand{font-size:21px;font-weight:900;letter-spacing:.3px}.brand b{color:var(--blue)}.back{font-size:12px;color:#9eb2c4}.wrap{max-width:1240px;margin:30px auto 70px;padding:0 22px}.hero{display:flex;align-items:center;justify-content:space-between;gap:20px;background:linear-gradient(135deg,#0b1a29,#0a1723);border:1px solid var(--line);border-radius:14px;padding:22px 24px;margin-bottom:18px}.server-title{display:flex;align-items:center;gap:15px}.server-icon{width:48px;height:48px;border-radius:12px;background:rgba(59,140,255,.12);color:#6aa5ff;display:grid;place-items:center;font-size:22px}.hero h1{font-size:22px;margin:0 0 5px}.hero-meta{color:var(--muted);font-size:12px}.status{display:inline-flex;align-items:center;gap:7px;padding:7px 11px;border-radius:20px;background:rgba(53,211,154,.1);color:var(--green);font-size:11px;font-weight:700}.status:before{content:'';width:7px;height:7px;border-radius:50%;background:currentColor}.alert{padding:13px 15px;border-radius:9px;margin-bottom:15px;border:1px solid}.ok{background:rgba(53,211,154,.08);border-color:rgba(53,211,154,.25);color:var(--green)}.err{background:rgba(255,97,117,.08);border-color:rgba(255,97,117,.25);color:#ff9baa}.overview{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.stat{background:var(--surface);border:1px solid var(--line);border-radius:11px;padding:16px}.stat span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px}.stat strong{font-size:14px;word-break:break-word}.content-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(330px,.75fr);gap:18px}.card{background:var(--surface);border:1px solid var(--line);border-radius:11px;overflow:hidden;margin-bottom:18px}.title{padding:15px 17px;background:#0d1d2c;border-bottom:1px solid var(--line);font-size:12px;font-weight:800;display:flex;align-items:center;justify-content:space-between}.body{padding:17px}.powers{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.btn{width:100%;border:1px solid transparent;border-radius:7px;padding:11px 13px;background:var(--blue);color:#fff;font-weight:750;cursor:pointer;transition:.15s}.btn:hover{filter:brightness(1.08)}.btn.green{background:#147f5d}.btn.orange{background:#986313}.btn.red{background:#a83f4c}.btn.secondary{background:#13283a;border-color:#29445d}.field{width:100%;padding:11px 12px;border:1px solid #29445d;background:var(--surface2);color:#fff;border-radius:7px;margin:7px 0 12px;outline:none}.field:focus{border-color:var(--blue)}.danger{border-color:rgba(255,97,117,.25)}.danger .title{color:#ff9baa}.note{font-size:11px;color:var(--muted);line-height:1.55;margin-bottom:12px}.credentials{display:grid;grid-template-columns:1fr 1.5fr;gap:10px}.credential{background:var(--surface2);border:1px solid var(--line);border-radius:8px;padding:13px}.credential label{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.45px;margin-bottom:7px}.password-row{display:flex;gap:7px;align-items:center}.password-row code{flex:1;font-size:13px;word-break:break-all}.mini{width:auto;padding:6px 9px;font-size:10px}.empty-password{font-size:11px;color:var(--muted);line-height:1.45}.section-help{font-size:10px;color:var(--muted);font-weight:400}.footer-note{text-align:center;color:#526b80;font-size:10px;margin-top:28px}@media(max-width:900px){.overview{grid-template-columns:1fr 1fr}.content-grid{grid-template-columns:1fr}.powers{grid-template-columns:1fr 1fr}}@media(max-width:560px){.top{height:60px;padding:0 15px}.brand{font-size:17px}.wrap{padding:0 13px;margin-top:18px}.hero{padding:16px;align-items:flex-start}.server-icon{width:40px;height:40px}.hero h1{font-size:18px}.overview{grid-template-columns:1fr 1fr;gap:8px}.stat{padding:12px}.credentials{grid-template-columns:1fr}.content-grid{display:block}.powers{grid-template-columns:1fr 1fr}.back{font-size:10px}.status{padding:5px 8px}.body{padding:14px}.title{padding:13px 14px}}</style></head><body><header class="top"><a class="brand" href="/client">NOD<b>EXA</b></a><a class="back" href="/client#vps">← Tilbage til Client Area</a></header><main class="wrap">@if(session('success'))<div class="alert ok">{{session('success')}}</div>@endif @if($errors->any())<div class="alert err">{{$errors->first()}}</div>@endif @if($apiError)<div class="alert err">Flax API: {{$apiError}}</div>@endif @php($currentPassword=$info['password']??$info['root_password']??$info['rootPassword']??$info['admin_password']??$info['adminPassword']??null) @php($osDisplay=(string)($info['os_name']??$info['operatingSystem']??'')) @php($osCollection=collect($oses)) @php($selectedOs=$osCollection->first(function($os) use ($vps){return (string)($os['id']??$os['value']??$os['template_id']??'')===(string)$vps->os_id;})) @php($selectedOsName=is_array($selectedOs)?(string)($selectedOs['name']??$selectedOs['label']??$selectedOs['title']??''):'') @php($isWindows=stripos($osDisplay.' '.$selectedOsName,'windows')!==false) @php($currentUser=$isWindows?'Administrator':($info['user']??$info['username']??$info['root_user']??'root'))<section class="hero"><div class="server-title"><div class="server-icon">▣</div><div><h1>{{$vps->hostname?:('VPS #'.$vps->id)}}</h1><div class="hero-meta">VPS #{{$vps->id}} · Flax server #{{$vps->provider_server_id?:'Ikke tilknyttet'}}</div></div></div><span class="status">{{str_replace('_',' ',$vps->status)}}</span></section><section class="overview"><div class="stat"><span>IP-adresse</span><strong>{{$vps->ip_address?:($info['ip_address']??$info['ip']??'Afventer IP')}}</strong></div><div class="stat"><span>Operativsystem</span><strong>{{$info['os_name']??$info['operatingSystem']??($selectedOsName?:('OS ID '.($vps->os_id?:'—')))}}</strong></div><div class="stat"><span>Hostname</span><strong>{{$vps->hostname?:($info['hostname']??'—')}}</strong></div><div class="stat"><span>Status</span><strong>{{$info['status']??$vps->status}}</strong></div></section><div class="content-grid"><div><section class="card"><div class="title"><span>Strømstyring</span><span class="section-help">Administrér VPS'ens strømstatus</span></div><div class="body powers">@foreach(['boot'=>['▶ Start','green'],'shutdown'=>['■ Luk ned','orange'],'restart'=>['↻ Genstart',''],'poweroff'=>['⚠ Tving sluk','red']] as $action=>$x)<form method="POST" action="/client/vps/{{$vps->id}}/power">@csrf<input type="hidden" name="action" value="{{$action}}"><button class="btn {{$x[1]}}" @if($action==='poweroff') onclick="return confirm('Vil du tvinge VPS’en til at slukke?')" @endif>{{$x[0]}}</button></form>@endforeach</div></section><section class="card"><div class="title"><span>Loginoplysninger</span><span class="section-help">SSH / Remote Desktop</span></div><div class="body credentials"><div class="credential"><label>Brugernavn</label><strong>{{$currentUser}}</strong></div><div class="credential"><label>Adgangskode</label>@if($currentPassword)<div class="password-row"><code id="vps-password" data-password="{{e($currentPassword)}}">••••••••••••</code><button type="button" class="btn mini secondary" onclick="var e=document.getElementById('vps-password');var shown=e.dataset.shown==='1';e.textContent=shown?'••••••••••••':e.dataset.password;e.dataset.shown=shown?'0':'1';this.textContent=shown?'Vis':'Skjul'">Vis</button><button type="button" class="btn mini secondary" onclick="navigator.clipboard.writeText(document.getElementById('vps-password').dataset.password)">Kopiér</button></div>@else<div class="empty-password">Den nuværende adgangskode returneres ikke af Flax API. Du kan oprette en ny i panelet til højre.</div>@endif</div></div></section></div><aside><section class="card"><div class="title">Nulstil adgangskode</div><form class="body" method="POST" action="/client/vps/{{$vps->id}}/reset-password">@csrf<div class="note">Opret en ny adgangskode til {{$isWindows?'Administrator':'root'}}-brugeren på VPS'en.</div><label class="section-help">Brugernavn</label><input class="field" name="user" value="{{$currentUser}}"><button class="btn">Nulstil adgangskode</button></form></section><section class="card danger"><div class="title">Geninstaller operativsystem</div><form class="body" method="POST" action="/client/vps/{{$vps->id}}/rebuild" onsubmit="return confirm('ADVARSEL: Alt data på VPS’en slettes permanent. Fortsæt?')">@csrf<div class="note"><strong style="color:#ff9baa">Advarsel:</strong> Geninstallation sletter alle filer og data på VPS'en permanent.</div><label class="section-help">Nyt operativsystem</label><select class="field" name="os_id" required><option value="">Vælg operativsystem...</option>@foreach($oses as $os) @php($oid=$os['id']??$os['value']??$os['template_id']??'') @php($on=$os['name']??$os['label']??$os['title']??('OS '.$oid))<option value="{{$oid}}" {{$oid==$vps->os_id?'selected':''}}>{{$on}}</option>@endforeach</select><input type="hidden" name="confirm" value="REINSTALL"><button class="btn red">Geninstaller VPS</button></form></section></aside></div><div class="footer-note">Nodexa VPS Management · Server #{{$vps->id}}</div></main></body></html>